import copy


DEFAULTS = {"host": "localhost", "port": 8080, "debug": False}


def load_config(text):
    """Parse 'key = value' lines into a config dict."""
    # Start from a copy of DEFAULTS to avoid modifying the original
    config = copy.copy(DEFAULTS)

    for line_num, line in enumerate(text.splitlines(), start=1):
        stripped_line = line.strip()

        # Skip blank lines and comments (lines starting with # after stripping)
        if not stripped_line or stripped_line.startswith('#'):
            continue

        # Check that the line contains an '=' sign
        if '=' not in line:
            raise ValueError(f"line {line_num}")

        # Split on the first '=' only, so values may contain '='
        key, value = line.split('=', 1)

        # Strip whitespace from key and value
        key = key.strip()
        value = value.strip()

        # Check that key is in DEFAULTS
        if key not in DEFAULTS:
            raise ValueError(f"line {line_num}")

        # Convert types based on the key
        if key == 'port':
            try:
                config['port'] = int(value)
            except ValueError:
                raise ValueError(f"line {line_num}")

        elif key == 'debug':
            value_lower = value.lower()
            if value_lower in ('true', 'false'):
                config['debug'] = (value_lower == 'true')
            else:
                raise ValueError(f"line {line_num}")

    return config
