def summarize(rows):
    """rows: list of dicts with 'category' and 'amount' strings. Return {category: total}."""
    totals = {}
    for row in rows:
        category = row["category"].strip().lower() if row.get("category") else ""

        # Skip empty categories
        if not category:
            continue

        amount_str = row["amount"]

        # Try to parse the amount, skip invalid amounts
        try:
            amount = float(amount_str.strip())
        except (ValueError, TypeError):
            continue

        # Add to totals for this category
        if category in totals:
            totals[category] += amount
        else:
            totals[category] = amount

    # Round each total to 2 decimal places
    return {k: round(v, 2) for k, v in totals.items()}
